CREATE LIGHTNING DATABASE ${source_db} DESCRIBE BY "SignSafe USL bounded public-source verification" OPTIONS ();
CREATE LIGHTNING REST TABLE dob_permits FROM ${source_db} REQUEST(endpoint "https://data.cityofnewyork.us/resource/ipu4-2q9a.json?zip_code=10017&%24select=permit_si_no%2Cbin__%2Cborough%2Cblock%2Clot%2Cissuance_date%2Cpermit_status&%24limit=20&%24order=%3Aid", method "get", response_type "json", http_encoding "URLENCODED") HEADER () BODY ();
CREATE LIGHTNING REST TABLE oath_fdny FROM ${source_db} REQUEST(endpoint "https://data.cityofnewyork.us/resource/jz4z-kudi.json?violation_location_zip_code=10017&issuing_agency=FIRE+DEPARTMENT+OF+NYC&%24select=ticket_number%2Cviolation_location_borough%2Cviolation_location_block_no%2Cviolation_location_lot_no%2Cviolation_date%2Chearing_status&%24limit=20", method "get", response_type "json", http_encoding "URLENCODED") HEADER () BODY ();
